{"title": "M365 explorer - seat estate treemap", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Seats by tenant and product; colour is utilisation.",
  "padding": 5,
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "signals": [
    {
      "name": "width",
      "update": "containerSize()[0]",
      "on": [
        {
          "events": "window:resize",
          "update": "containerSize()[0]"
        }
      ]
    },
    {
      "name": "height",
      "update": "containerSize()[1]",
      "on": [
        {
          "events": "window:resize",
          "update": "containerSize()[1]"
        }
      ]
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {
        "%context%": true,
        "%timefield%": "timestamp",
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.m365.event_type": "license"
                      }
                    },
                    {
                      "term": {
                        "data.m365.license_class": "paid"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "tenant": {
                  "terms": {
                    "field": "data.m365.tenant_name",
                    "size": 50
                  },
                  "aggs": {
                    "product": {
                      "terms": {
                        "field": "data.m365.sku_display_name",
                        "size": 40
                      },
                      "aggs": {
                        "seats": {
                          "max": {
                            "field": "data.m365.usable_units"
                          }
                        },
                        "util": {
                          "max": {
                            "field": "data.m365.utilization_pct"
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.tenant.buckets"
      },
      "transform": [
        {
          "type": "flatten",
          "fields": [
            "product.buckets"
          ],
          "as": [
            "product"
          ]
        },
        {
          "type": "formula",
          "expr": "datum.key",
          "as": "tenant"
        },
        {
          "type": "formula",
          "expr": "datum.product.key",
          "as": "sku"
        },
        {
          "type": "formula",
          "expr": "datum.product.seats.value",
          "as": "seats"
        },
        {
          "type": "formula",
          "expr": "datum.product.util.value",
          "as": "util"
        },
        {
          "type": "filter",
          "expr": "datum.seats > 0"
        }
      ]
    },
    {
      "name": "tree",
      "source": "raw",
      "transform": [
        {
          "type": "nest",
          "keys": [
            "tenant"
          ],
          "generate": true
        },
        {
          "type": "treemap",
          "field": "seats",
          "method": "squarify",
          "padding": 2,
          "round": true,
          "sort": {
            "field": "value",
            "order": "descending"
          },
          "size": [
            {
              "signal": "width"
            },
            {
              "signal": "height"
            }
          ]
        }
      ]
    },
    {
      "name": "leaves",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "!datum.children"
        }
      ]
    },
    {
      "name": "groups",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.children"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "util",
      "type": "linear",
      "domain": [
        0,
        100
      ],
      "range": {
        "scheme": "redyellowgreen"
      }
    },
    {
      "name": "tenant",
      "type": "ordinal",
      "domain": {
        "data": "raw",
        "field": "tenant"
      },
      "range": [
        "#54B399",
        "#6092C0",
        "#D36086",
        "#9170B8",
        "#CA8EAE",
        "#D6BF57",
        "#B9A888",
        "#DA8B45",
        "#AA6556",
        "#E7664C"
      ]
    }
  ],
  "legends": [
    {
      "fill": "util",
      "type": "gradient",
      "title": "Utilisation %",
      "orient": "bottom",
      "direction": "horizontal"
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "leaves"
      },
      "encode": {
        "enter": {
          "stroke": {
            "value": "#fff"
          },
          "tooltip": {
            "signal": "datum.tenant + ' / ' + datum.sku + ': ' + datum.seats + ' seats, ' + format(datum.util, '.1f') + '%'"
          }
        },
        "update": {
          "x": {
            "field": "x0"
          },
          "y": {
            "field": "y0"
          },
          "x2": {
            "field": "x1"
          },
          "y2": {
            "field": "y1"
          },
          "fill": {
            "scale": "util",
            "field": "util"
          }
        }
      }
    },
    {
      "type": "rect",
      "from": {
        "data": "groups"
      },
      "encode": {
        "enter": {
          "fill": {
            "value": "transparent"
          },
          "stroke": {
            "value": "#333"
          },
          "strokeWidth": {
            "value": 2
          }
        },
        "update": {
          "x": {
            "field": "x0"
          },
          "y": {
            "field": "y0"
          },
          "x2": {
            "field": "x1"
          },
          "y2": {
            "field": "y1"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "groups"
      },
      "interactive": false,
      "encode": {
        "enter": {
          "font": {
            "value": "Helvetica Neue, Arial"
          },
          "fontSize": {
            "value": 12
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "value": "#333"
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "top"
          }
        },
        "update": {
          "x": {
            "signal": "datum.x0 + 4"
          },
          "y": {
            "signal": "datum.y0 + 3"
          },
          "text": {
            "signal": "datum.tenant || datum.key || datum.name"
          },
          "opacity": {
            "signal": "(datum.x1 - datum.x0) > 70 ? 1 : 0"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "leaves"
      },
      "interactive": false,
      "encode": {
        "enter": {
          "font": {
            "value": "Helvetica Neue, Arial"
          },
          "fontSize": {
            "value": 10
          },
          "fill": {
            "value": "#000"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          }
        },
        "update": {
          "x": {
            "signal": "(datum.x0 + datum.x1) / 2"
          },
          "y": {
            "signal": "(datum.y0 + datum.y1) / 2"
          },
          "text": {
            "field": "sku"
          },
          "opacity": {
            "signal": "(datum.x1 - datum.x0) > 60 && (datum.y1 - datum.y0) > 16 ? 1 : 0"
          }
        }
      }
    }
  ]
}"}}

{"title": "M365 explorer - seat headroom by tenant", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Assigned versus purchased seats; the bar is the headroom.",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "timestamp",
      "index": "wazuh-alerts-*",
      "body": {
        "size": 0,
        "aggs": {
          "scoped": {
            "filter": {
              "bool": {
                "filter": [
                  {
                    "term": {
                      "data.m365.event_type": "tenant_summary"
                    }
                  }
                ]
              }
            },
            "aggs": {
              "tenant": {
                "terms": {
                  "field": "data.m365.tenant_name",
                  "size": 50,
                  "order": {
                    "seats": "desc"
                  }
                },
                "aggs": {
                  "seats": {
                    "max": {
                      "field": "data.m365.total_usable_units"
                    }
                  },
                  "assigned": {
                    "max": {
                      "field": "data.m365.total_assigned_units"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.scoped.tenant.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.key",
      "as": "tenant"
    },
    {
      "calculate": "datum.seats.value",
      "as": "seats"
    },
    {
      "calculate": "datum.assigned.value",
      "as": "assigned"
    },
    {
      "calculate": "datum.seats.value - datum.assigned.value",
      "as": "free"
    }
  ],
  "encoding": {
    "y": {
      "field": "tenant",
      "type": "nominal",
      "title": null,
      "sort": {
        "field": "seats",
        "order": "descending"
      },
      "axis": {
        "labelLimit": 220
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rule",
        "size": 3,
        "color": "#D3DAE6"
      },
      "encoding": {
        "x": {
          "field": "assigned",
          "type": "quantitative",
          "title": "Seats"
        },
        "x2": {
          "field": "seats"
        }
      }
    },
    {
      "transform": [
        {
          "fold": [
            "assigned",
            "seats"
          ],
          "as": [
            "measure",
            "value"
          ]
        }
      ],
      "mark": {
        "type": "point",
        "filled": true,
        "size": 160,
        "opacity": 1
      },
      "encoding": {
        "x": {
          "field": "value",
          "type": "quantitative"
        },
        "color": {
          "field": "measure",
          "type": "nominal",
          "title": null,
          "scale": {
            "domain": [
              "assigned",
              "seats"
            ],
            "range": [
              "#54B399",
              "#6092C0"
            ]
          }
        },
        "tooltip": [
          {
            "field": "tenant",
            "type": "nominal"
          },
          {
            "field": "measure",
            "type": "nominal"
          },
          {
            "field": "value",
            "type": "quantitative"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 10,
        "fontSize": 11,
        "color": "#69707D"
      },
      "encoding": {
        "x": {
          "field": "seats",
          "type": "quantitative"
        },
        "text": {
          "field": "free",
          "type": "quantitative",
          "format": ".0f"
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": "transparent"
    }
  }
}"}}

